def render_list(renderer: 'BaseRenderer', token: Dict[str, Any], state:
    'BlockState') ->str:
    attrs = token['attrs']
    if attrs.get('ordered'):
        children = _render_ordered_list(renderer, token, state)
    else:
        children = _render_unordered_list(renderer, token, state)
    text = ''.join(children)
    parent = token.get('parent')
    if parent:
        if parent['tight']:
            return text
    return text + '\n'


def _render_list_item(renderer: 'BaseRenderer', parent: Dict[str, Any],
    item: Dict[str, Any], state: 'BlockState') ->str:
    children = item.get('children', [])
    if not children:
        return ''

    tight = parent.get('tight', False)
    if tight:
        text = ''
        for child in children:
            child = cast(Dict[str, Any], child)
            if child['type'] == 'list':
                child['parent'] = parent
            elif child['type'] == 'blank_line':
                continue
            text += renderer.render_token(child, state)
        return strip_end(text, '\n')
    else:
        text = ''
        for child in children:
            child = cast(Dict[str, Any], child)
            if child['type'] == 'list':
                child['parent'] = parent
            text += renderer.render_token(child, state)
        return strip_end(text, '\n')


def _render_ordered_list(renderer: 'BaseRenderer', token: Dict[str, Any],
    state: 'BlockState') ->Iterable[str]:
    attrs = token['attrs']
    start = attrs.get('start', 1)
    children = token.get('children', [])
    for index, item in enumerate(children):
        item = cast(Dict[str, Any], item)
        body = _render_list_item(renderer, token['attrs'], item, state)
        yield renderer.list_item(body, index + start)


def _render_unordered_list(renderer: 'BaseRenderer', token: Dict[str, Any],
